	"github.com/cockroachdb/errors"
	"github.com/cockroachdb/pebble/internal/base"
	"github.com/cockroachdb/redact"
)

// BatchDurableInfo contains the info for a BatchDurable event.
type BatchDurableInfo struct {
	// JobID is a unique identifier for this durability event. It may be passed
	// to DB.WaitForJobDurability.
	JobID int
	// SeqNum is the base sequence number of the committed batch.
	SeqNum base.SeqNum
	// Err is the error encountered while writing or syncing the batch to the
	// WAL, if any.
	Err error
	// ApplyDuration is the time spent applying the batch to the memtable.
	ApplyDuration time.Duration
	// SyncDuration is the time between the batch being written to the WAL and
	// the WAL sync covering it completing.
	SyncDuration time.Duration
	// CorrelationID is WriteOptions.CommitCorrelationID of the commit.
	CorrelationID uint64
	// BatchSize is the size of the encoded batch in bytes.
	BatchSize int
	// KeyCount is the number of entries in the batch.
	KeyCount uint32
}

func (i BatchDurableInfo) String() string {
	return redact.StringWithoutMarkers(i)
}

// SafeFormat implements redact.SafeFormatter.
func (i BatchDurableInfo) SafeFormat(w redact.SafePrinter, _ rune) {
	if i.Err != nil {
		w.Printf("[JOB %d] batch durable error (seqnum %d): %s",
			redact.Safe(i.JobID), redact.Safe(i.SeqNum), i.Err)
		return
	}
	w.Printf("[JOB %d] batch durable (seqnum %d, %d keys, %d bytes): apply %.3fs, sync %.3fs",
		redact.Safe(i.JobID), redact.Safe(i.SeqNum), redact.Safe(i.KeyCount),
		redact.Safe(i.BatchSize), redact.Safe(i.ApplyDuration.Seconds()),
		redact.Safe(i.SyncDuration.Seconds()))
}

// DurabilityStats is a snapshot of the durability state of a DB, as returned
// by DB.DurabilityStats.
type DurabilityStats struct {
	// HighestDurableSeqNum is the highest sequence number known to be durable.
	HighestDurableSeqNum base.SeqNum
	// FirstErr is the first WAL sync error observed, if any.
	FirstErr error
	// PendingWaiters is the number of goroutines currently blocked in the
	// DB.WaitFor*Durability* methods.
	PendingWaiters int64
	// TotalDurableCommits is the number of Sync commits that became durable.
	TotalDurableCommits uint64
	// TotalFailedCommits is the number of Sync commits whose WAL write or sync
	// failed.
	TotalFailedCommits uint64
	// CumulativeSyncDuration is the sum of the SyncDurations of all durable
	// commits.
	CumulativeSyncDuration time.Duration
	// MaxSyncDuration is the largest SyncDuration of any durable commit.
	MaxSyncDuration time.Duration
}

var (
	// ErrDurabilityJobExpired is returned by DB.WaitForJobDurability when the
	// job ID has fallen out of the bounded retention window.
	ErrDurabilityJobExpired = errors.New("pebble: durability job expired from retention window")
	// ErrDurabilityJobUnknown is returned by DB.WaitForJobDurability when the
	// job ID was never issued by a BatchDurable event.
	ErrDurabilityJobUnknown = errors.New("pebble: unknown durability job")
	// ErrDurabilityNotifyLimit is delivered by DB.DurabilityNotify when too many
	// subscriptions are outstanding.
	ErrDurabilityNotifyLimit = errors.New("pebble: too many outstanding durability subscriptions")
)

const (
	// durableJobRetention is the number of most recent BatchDurable job results
	// retained for DB.WaitForJobDurability.
	durableJobRetention = 1024
	// maxDurabilitySubscriptions bounds the number of outstanding
	// DB.DurabilityNotify subscriptions.
	maxDurabilitySubscriptions = 4096
)

// batchDurableState is the per-batch state used to report durability of a
// Sync commit.
type batchDurableState struct {
	// pendingDB is set when the commit used ApplyNoSyncWait and the durability
	// event must be reported by Batch.SyncWait.
	pendingDB     *DB
	walStart      crtime.Mono
	applyDuration time.Duration
	correlationID uint64
	size          int
	keyCount      uint32
}

func noopBatchDurable(BatchDurableInfo) {}

// batchDurableConfigured returns true if the listener has a user-provided
// BatchDurable callback (as opposed to the no-op installed by EnsureDefaults).
func batchDurableConfigured(l *EventListener) bool {
	if l == nil || l.BatchDurable == nil {
		return false
	}
	return reflect.ValueOf(l.BatchDurable).Pointer() != reflect.ValueOf(noopBatchDurable).Pointer()
}

func teeBatchDurable(a, b func(BatchDurableInfo)) func(BatchDurableInfo) {
	aSet := batchDurableConfigured(&EventListener{BatchDurable: a})
	bSet := batchDurableConfigured(&EventListener{BatchDurable: b})
	switch {
	case aSet && bSet:
		return func(info BatchDurableInfo) {
			a(info)
			b(info)
		}
	case aSet:
		return a
	case bSet:
		return b
	default:
		return noopBatchDurable
	}
}

type durableJob struct {
	id  int
	err error
}

type durabilitySub struct {
	seqNum base.SeqNum
	ch     chan error
}

// durabilityTracker tracks the highest durable sequence number of a DB and
// the waiters and subscribers interested in it.
type durabilityTracker struct {
	// listenerConfigured is set at Open if EventListener.BatchDurable is
	// configured. Job IDs and metrics are only maintained in that case.
	listenerConfigured bool

	mu struct {
		sync.Mutex
		highest  base.SeqNum
		firstErr error
		closed   bool
		// changed is closed (and reset to nil) whenever the state changes. It
		// is lazily created by waiters.
		changed        chan struct{}
		pendingWaiters int64
		subs           []durabilitySub

		totalDurable uint64
		totalFailed  uint64
		cumSync      time.Duration
		maxSync      time.Duration

		listenerCount   uint64
		listenerSyncDur time.Duration

		lastJobID int
		jobs      [durableJobRetention]durableJob
	}
}

// record records the outcome of a Sync commit covering sequence numbers
// [seqNum, seqNum+count). It returns the job ID assigned to the event, or 0
// if the BatchDurable listener is not configured.
func (t *durabilityTracker) record(
	seqNum base.SeqNum, count uint32, err error, syncDuration time.Duration,
) int {
	t.mu.Lock()
	defer t.mu.Unlock()
	if err != nil {
		t.mu.totalFailed++
		if t.mu.firstErr == nil {
			t.mu.firstErr = err
		}
	} else {
		t.mu.totalDurable++
		t.mu.cumSync += syncDuration
		t.mu.maxSync = max(t.mu.maxSync, syncDuration)
		if count > 0 {
			t.mu.highest = max(t.mu.highest, seqNum+base.SeqNum(count)-1)
		}
		if t.listenerConfigured {
			t.mu.listenerCount++
			t.mu.listenerSyncDur += syncDuration
		}
	}
	var jobID int
	if t.listenerConfigured {
		t.mu.lastJobID++
		jobID = t.mu.lastJobID
		t.mu.jobs[jobID%durableJobRetention] = durableJob{id: jobID, err: err}
	}
	t.notifyLocked()
	return jobID
}

func (t *durabilityTracker) close() {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.mu.closed = true
	t.notifyLocked()
}

// notifyLocked wakes all waiters and delivers results to any subscriptions
// that are resolved by the current state.
func (t *durabilityTracker) notifyLocked() {
	if t.mu.changed != nil {
		close(t.mu.changed)
		t.mu.changed = nil
	}
	subs := t.mu.subs[:0]
	for _, s := range t.mu.subs {
		if done, err := t.resolvedLocked(s.seqNum); done {
			s.ch <- err
		} else {
			subs = append(subs, s)
		}
	}
	clear(t.mu.subs[len(subs):])
	t.mu.subs = subs
}

// resolvedLocked returns whether a wait for seqNum is resolved, and if so the
// result. Close and durability errors take precedence over success for
// sequence numbers that are not yet durable.
func (t *durabilityTracker) resolvedLocked(seqNum base.SeqNum) (bool, error) {
	if t.mu.closed {
		return true, ErrClosed
	}
	if seqNum <= t.mu.highest {
		return true, nil
	}
	if t.mu.firstErr != nil {
		return true, t.mu.firstErr
	}
	return false, nil
}

func (t *durabilityTracker) wait(ctx context.Context, seqNum base.SeqNum) error {
	if ctx == nil {
		ctx = context.Background()
	}
	t.mu.Lock()
	for {
		if done, err := t.resolvedLocked(seqNum); done {
			t.mu.Unlock()
			return err
		}
		if err := ctx.Err(); err != nil {
			t.mu.Unlock()
			return err
		}
		if t.mu.changed == nil {
			t.mu.changed = make(chan struct{})
		}
		ch := t.mu.changed
		t.mu.pendingWaiters++
		t.mu.Unlock()
		select {
		case <-ch:
		case <-ctx.Done():
		}
		t.mu.Lock()
		t.mu.pendingWaiters--
	}
}

func (t *durabilityTracker) waitJob(ctx context.Context, jobID int) error {
	if ctx == nil {
		ctx = context.Background()
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.mu.closed {
		return ErrClosed
	}
	// Job IDs are only issued once the commit's durability outcome is known,
	// so a known job never requires blocking.
	switch {
	case jobID <= 0 || jobID > t.mu.lastJobID:
		return errors.Wrapf(ErrDurabilityJobUnknown, "job %d", errors.Safe(jobID))
	case jobID <= t.mu.lastJobID-durableJobRetention:
		return errors.Wrapf(ErrDurabilityJobExpired, "job %d", errors.Safe(jobID))
	}
	j := t.mu.jobs[jobID%durableJobRetention]
	if j.id != jobID {
		return errors.AssertionFailedf("durability job %d not found in retention window", errors.Safe(jobID))
	}
	if j.err != nil {
		return j.err
	}
	return ctx.Err()
}

func (t *durabilityTracker) notify(seqNum base.SeqNum) <-chan error {
	ch := make(chan error, 1)
	t.mu.Lock()
	defer t.mu.Unlock()
	if done, err := t.resolvedLocked(seqNum); done {
		ch <- err
	} else if len(t.mu.subs) >= maxDurabilitySubscriptions {
		ch <- ErrDurabilityNotifyLimit
	} else {
		t.mu.subs = append(t.mu.subs, durabilitySub{seqNum: seqNum, ch: ch})
	}
	return ch
}

func (t *durabilityTracker) state() (base.SeqNum, error) {
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.mu.highest, t.mu.firstErr
}

func (t *durabilityTracker) stats() DurabilityStats {
	t.mu.Lock()
	defer t.mu.Unlock()
	return DurabilityStats{
		HighestDurableSeqNum:   t.mu.highest,
		FirstErr:               t.mu.firstErr,
		PendingWaiters:         t.mu.pendingWaiters,
		TotalDurableCommits:    t.mu.totalDurable,
		TotalFailedCommits:     t.mu.totalFailed,
		CumulativeSyncDuration: t.mu.cumSync,
		MaxSyncDuration:        t.mu.maxSync,
	}
}

func (t *durabilityTracker) listenerMetrics() (uint64, time.Duration) {
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.mu.listenerCount, t.mu.listenerSyncDur
}

// measuredDuration returns d, rounded up to the minimum clock resolution so
// that a measured phase is never reported as taking zero time.
func measuredDuration(d time.Duration) time.Duration {
	return max(d, time.Nanosecond)
}

// onBatchDurable is called exactly once per Sync commit once the outcome of
// the WAL sync for b is known.
func (d *DB) onBatchDurable(b *Batch, err error) {
	var syncDuration time.Duration
	if b.durable.walStart != 0 {
		syncDuration = measuredDuration(b.durable.walStart.Elapsed())
	}
	applyDuration := b.durable.applyDuration
	if err == nil {
		applyDuration = measuredDuration(applyDuration)
	}
	seqNum := b.SeqNum()
	jobID := d.durability.record(seqNum, b.durable.keyCount, err, syncDuration)
	if d.durability.listenerConfigured {
		d.opts.EventListener.BatchDurable(BatchDurableInfo{
			JobID:         jobID,
			SeqNum:        seqNum,
			Err:           err,
			ApplyDuration: applyDuration,
			SyncDuration:  syncDuration,
			CorrelationID: b.durable.correlationID,
			BatchSize:     b.durable.size,
			KeyCount:      b.durable.keyCount,
		})
	}
}

// WaitForDurability blocks until seqNum is durable in the WAL. A sequence
// number of zero is satisfied immediately. It returns an error if a WAL sync
// fails before seqNum becomes durable or if the DB is closed. It returns nil
// immediately if the WAL is disabled.
//
// Durability advances only when a Sync commit completes; a sequence number
// written by a non-Sync commit becomes durable once a subsequent Sync commit
// completes.
func (d *DB) WaitForDurability(seqNum base.SeqNum) error {
	return d.WaitForDurabilityContext(context.Background(), seqNum)
}

// WaitForDurabilityContext is like WaitForDurability, but also returns if ctx
// is done. Durability and close errors take precedence over ctx's error.
func (d *DB) WaitForDurabilityContext(ctx context.Context, seqNum base.SeqNum) error {
	if d.opts.DisableWAL {
		return nil
	}
	return d.durability.wait(ctx, seqNum)
}

// WaitForDurabilityBatch blocks until every sequence number in seqNums is
// durable. It returns nil for a nil or empty slice. See WaitForDurability.
func (d *DB) WaitForDurabilityBatch(seqNums []base.SeqNum) error {
	return d.WaitForDurabilityBatchContext(context.Background(), seqNums)
}

// WaitForDurabilityBatchContext is like WaitForDurabilityBatch, but also
// returns if ctx is done. Durability and close errors take precedence over
// ctx's error.
func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqNums []base.SeqNum) error {
	if len(seqNums) == 0 || d.opts.DisableWAL {
		return nil
	}
	// Durability is monotonic, so waiting for the largest sequence number
	// suffices.
	var maxSeqNum base.SeqNum
	for _, s := range seqNums {
		maxSeqNum = max(maxSeqNum, s)
	}
	return d.durability.wait(ctx, maxSeqNum)
}

// WaitForJobDurability returns the outcome of the commit identified by a
// BatchDurableInfo.JobID. Only the most recent jobs are retained; older jobs
// return an error wrapping ErrDurabilityJobExpired. Zero or never-issued job
// IDs return an error wrapping ErrDurabilityJobUnknown.
func (d *DB) WaitForJobDurability(jobID int) error {
	return d.WaitForJobDurabilityContext(context.Background(), jobID)
}

// WaitForJobDurabilityContext is like WaitForJobDurability, but also returns
// ctx's error if ctx is done. Durability and close errors take precedence over
// ctx's error.
func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
	if d.opts.DisableWAL {
		return nil
	}
	return d.durability.waitJob(ctx, jobID)
}

// DurableState returns the highest durable sequence number and the first WAL
// sync error observed, if any.
func (d *DB) DurableState() (base.SeqNum, error) {
	return d.durability.state()
}

// DurabilityNotify returns a channel that receives a single value once seqNum
// is durable (nil) or can no longer become durable (a WAL sync error or
// ErrClosed). If too many subscriptions are outstanding, the returned channel
// immediately delivers ErrDurabilityNotifyLimit. The channel is buffered, so
// the caller is never required to receive from it.
func (d *DB) DurabilityNotify(seqNum base.SeqNum) <-chan error {
	if d.opts.DisableWAL {
		ch := make(chan error, 1)
		ch <- nil
		return ch
	}
	return d.durability.notify(seqNum)
}

// DurabilityStats returns a snapshot of the DB's durability state.
func (d *DB) DurabilityStats() DurabilityStats {
	return d.durability.stats()
}

